"""Receipt-driven front pages; archived lanes stay in a separate history page."""
from __future__ import annotations

from html import escape as e
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
BASE = "docs/research/2026-10-26-gdx/"


def load(name):
    return json.loads((ROOT / BASE / name).read_text())


def metric(row):
    return f'{row["value"]:.5f} [{row["ci95"][0]:.5f}, {row["ci95"][1]:.5f}]'


def frame(title, body, active="Overview"):
    nav = [("Overview", "index.html"), ("Submission guide", "executive-summary.html"),
           ("GDX-1 science", "geothermal-chemistry-review.html"), ("Nine-site review", "priority-executive-summary.html"),
           ("Archive", "research-history.html")]
    links = "".join(f'<a href="{url}"' + (' aria-current="page"' if label == active else '') + f'>{label}</a>' for label, url in nav)
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{e(title)} · GEMSDOE30</title><meta name="description" content="Evidence-first DOE GEMS fault-discovery research. Downloadable research is not submission approval.">
<link rel="stylesheet" href="docs/assets/research.css"><script src="docs/assets/research.js" defer></script></head>
<body><a class="skip" href="#main">Skip to evidence</a><header class="site-header"><div class="nav-wrap"><a class="brand" href="index.html"><span class="brand-mark">G30</span>Fault discovery / research</a><nav aria-label="Main navigation">{links}</nav></div></header>
<main id="main">{body}</main><footer><div><strong>Maximize P(Win). Own the Outcome.</strong><p>Negative findings save scarce submission slots. No automated competition access or upload.</p></div><div><a href="docs/research/2026-10-26-gdx/run-card.json">Canonical JSON run card</a><a href="https://github.com/buffedlizard55-lab/GEMSDOE30">Source repository</a><a href="docs/status.json">Machine status</a></div><p class="fine">Review date: 26 October 2026 UTC. Public snapshots are pinned, not a live leaderboard. Remote priority sites were read, not modified. Historical claims and local proxy metrics are not organizer-confirmed scores.</p></footer></body></html>'''


def release(c):
    return f'''<section class="release" aria-labelledby="release-title"><div class="release-heading"><span class="pill failed">NOT APPROVED FOR SUBMISSION</span><span class="pill caution">New research artifact · GDX-1</span></div>
<h2 id="release-title">Downloadable and format-valid. <span>Not supported for promotion.</span></h2><p>Site-deduplicated, effort-normalized geothermal chemistry plus local geophysical edges. It failed the preregistered paired improvement gate against both controls. <strong>Do not spend a weekly slot.</strong> No retuning, no competition upload, no slot selected.</p>
<div class="actions"><a class="button" href="{e(c['published_tiff'])}" download>Download GDX-1 research TIFF <span>474 KiB · do not upload</span></a><a class="button secondary" href="{BASE}run-card.json">Read JSON decision</a></div>
<p class="filename">{e(Path(c['published_tiff']).name)}</p><details><summary>Exact byte identity and file guarantees</summary><dl><dt>SHA-256</dt><dd><code>{c['raster_sha256']}</code></dd><dt>Grid</dt><dd>1 float32 band · EPSG:32611 · 3730 × 3292 · 100 m · exact mirrored-template affine transform</dd><dt>Values</dt><dd>Finite [0,1] in all 5,167,373 footprint cells; NaN nodata outside; 44,090 binary dots; zero on / within 2 pixels of the 60,988 catalogue positives; ≥3 pixel dot spacing.</dd><dt>Scope</dt><dd>Automated local checks passed. This is not proof of portal acceptance or leaderboard performance. No organizer receipt exists.</dd></dl></details></section>'''


def holdout(c):
    h = c["holdout"]
    rows = [("Core19 control", h["comparators"]["core19"]), ("Sampling-effort control", h["comparators"]["effort6"]), ("GDX-1 candidate", h)]
    table = "".join(f'<tr><th scope="row">{label}</th><td>{metric(row)}</td><td>60,988</td><td>{"Negative: no demonstrated improvement" if label.startswith("GDX") else "Same folds, buffer, labels and dot counts"}</td></tr>' for label, row in rows)
    delta = "".join(f'<li>GDX−{name}: <strong>{metric(value)}</strong></li>' for name, value in h["candidate_minus"].items())
    return f'''<section class="section" id="holdout"><div class="section-heading"><h2>One honest comparison.</h2><p>Local spatial proxy, not a competition score.</p></div><div class="table-wrap"><table><caption>HOLDOUT-DTI · 46 px buffer · α 0.2 / β 0.8 · 300 m triangular kernel</caption><thead><tr><th>Model</th><th>Pooled DTI [95% CI]</th><th>Withheld positives</th><th>Decision</th></tr></thead><tbody>{table}</tbody></table></div><ul class="spaced">{delta}</ul><p class="fine">Evaluator <code>{e(h['evaluator_version'])}</code>; protocol <code>{e(h['protocol_version'])}</code>. Four whole-component spatial folds; catalogue-derived construction can use visible faults only, which are masked pixel-exactly. Both paired lower confidence bounds must exceed zero; neither did. 2,000 paired 128-pixel geographic-block bootstrap replicates, seed 3071, 371 blocks. The CI is conditional on mapped-fault recovery, not calibrated uncertainty for hidden unmapped faults.</p><p class="fine">The archived 17 px Core19 value 0.13982063017811727 was reproduced within 1e−9 solely to establish evaluator parity. It is not the candidate’s 46 px comparator and does not establish superiority to the missing strongest comparable control. Organizer-confirmed score: <strong>none</strong>. Leaderboard forecast: <strong>not defensible</strong>.</p></section>'''


def novelty(c, ready):
    rows = "".join(f'<tr><th scope="row">{e(g["name"])}</th><td><span class="gate {g["status"]}">{e(g["status"])}</span></td><td>{e(g["detail"])}</td></tr>' for g in ready["gates"])
    return f'''<section class="section" id="novelty"><h2>Different mechanism. Uniqueness still incomplete.</h2><p>The continuous surface was audited <strong>before dot placement</strong>, and final dots were audited separately. In the frozen registry, 327 references were successfully compared at each stage: maximum surface Spearman <strong>0.164702</strong>, final-dot Spearman <strong>0.091798</strong>, and candidate dots within 3 px of any one reference <strong>54.2459%</strong>. No observed comparison crosses ρ &gt;0.90 or overlap &gt;70%.</p><p><strong>That is not global uniqueness clearance.</strong> One pinned GEMSDOE31 reference has 2,610,312 non-finite in-footprint cells. It remains UNKNOWN at both stages; no imputation or finite-subset correlation was used. The first attempt stopped. A documented <a href="{BASE}amendment-A1.md">A1 amendment</a> permitted one exact-saved-array/surface exploratory recovery, with no refitting or parameter changes. This deviation cannot authorize submission.</p><p>A separate local addendum checked the FFL-1 artifact at both stages (surface ρ 0.077351; dot overlap 44.5339%). Thus 328 successful comparisons plus one malformed reference are documented overall. Private/parallel coverage and five unverified original-surface paths remain incomplete. Later public arrivals become blocking UNKNOWN coverage without rewriting frozen receipts.</p><div class="table-wrap"><table><caption>Machine-checked gates; failed and unknown both block promotion</caption><thead><tr><th>Gate</th><th>Status</th><th>Reason</th></tr></thead><tbody>{rows}</tbody></table></div><p class="fine">Three experiments accounted conservatively: failed pre-placement attempt + exact-surface recovery + historical parity check; 603.478 seconds from the original timer, including the pause. The 3/3 cap is exhausted. 28 exact inputs tested alone in each of four folds (112 canaries), no AUC alarm &gt;0.90; maximum bidirectional raw/univariate AUC 0.639961. Absence of a canary alarm is not proof of no leakage.</p></section>'''


def sources():
    return '''<section class="section" id="sources"><h2>Sources, with access limits visible.</h2><div class="resource-grid"><article><h3>Official competition</h3><p>Problem description, rules, leaderboard and current eligibility. Links are provided for provenance; no fresh leaderboard or deadline is claimed.</p><a href="https://www.drivendata.org/competitions/306/competition-doe-gems/page/967/">Official problem description ↗</a><p><a href="https://www.drivendata.org/competitions/306/competition-doe-gems/leaderboard/">Official leaderboard ↗</a></p><a href="https://docs.nlr.gov/docs/fy26osti/96647.pdf">Official rules PDF ↗</a></article><article><h3>Official reference code</h3><p>Pinned GitHub README / notebook were freshly retrieved. The 19 channel descriptions, five Monte Carlo splits and Tversky training loss do not authenticate mirror inputs or hidden scoring.</p><a href="https://github.com/drivendataorg/gems-prize-reference-solution/tree/aebe92f7c8a990f0e3443451b7a825d9afd6336b">Pinned organizer reference ↗</a><p><a href="docs/research/2026-10-26-gdx/sources.json">Extracts, metadata and source hashes</a></p></article><article><h3>Geothermal field data</h3><p>USGS mapped geology / structure and DOE GDR 1391 underpin the mechanism. Source hosts were not freshly reachable in this sandbox; exact input hashes and earlier acquisition receipts are preserved.</p><a href="https://doi.org/10.15121/1881483">DOE GDR / INGENIOUS DOI ↗</a><p><a href="https://doi.org/10.5066/P93LGLVQ">USGS GeoDAWN DOI ↗</a></p><a href="docs/research/geothermal-vents-knowledge.md">Existing science/source ledger</a></article></div><p class="fine">Owner mirrors are byte-pinned, not organizer-authenticated. Geophysical channel labels alone do not establish all physical units. Scalar strain invariants do not supply stress azimuth; observation-location rasters do not measure heat anomalies. Prior notes must not be advertised as newly fetched primary evidence.</p></section>'''


def archive_note():
    return '''<section class="section"><h2>Earlier artifacts are not fallback submissions.</h2><p>The archived G30-TAD 51.44% overlap finding covered a frozen 193-reference snapshot, not today’s full parallel inventory. PTA-1, geothermal-corridor, FFL-1 and H-NEARSPLAY also have unresolved or negative gates. Current additive coverage is checked separately from historical evidence; no historical pass is silently inherited.</p><p><a href="research-history.html">Archived executive summary and research downloads</a> · <a href="geothermal-tilt-alteration-review.html">G30-TAD review</a> · <a href="experiment-review.html">Stopped-attempt evidence</a> · <a href="receipt-integrity-review.html">FFL receipt audit</a></p></section>'''


def priority_table(fleet):
    rows = []
    for r in fleet["rows"]:
        rows.append(f'''<tr><th scope="row"><a href="priority-{r['site']}.html">{r['site']}</a></th><td>{r['quoted_owner_claim']}<br><small>owner-reported, unverified</small></td><td><a href="{e(r['source_url'])}?raw=true"><code>{e(r['historical_file'])}</code></a></td><td>{r['dots']:,}</td><td>No new submission; no forecast</td></tr>''')
    return f'''<div class="table-wrap"><table><caption>Nine priority repositories · historical files named in the prompt · not a live ranking</caption><thead><tr><th>Repository review</th><th>Historical claim (NOT verified score)</th><th>Exact historical filename / source bytes</th><th>Dot count</th><th>Submit?</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div>'''


def lineage():
    return '''<section class="section" id="h33"><h2>Why H33-B2 looks better in the supplied history.</h2><p>The byte-level explanation is <strong>precision-oriented pruning, not a newly discovered geological signal</strong>. Reopening the files proves the path <strong>44,090 d28 dots → 40,199 r1 dots → 37,654 H33-B2 dots</strong>. The first pruning removes 3,891 dots within 1 pixel of the visible catalogue; H33 removes another 2,545 dots within 2 pixels. The H33 set is exactly that distance-pruned r1 subset. GEMSDOE25 / GEMSDOE30 are value-identical; GEMSDOE28 r1 / GEMSDOE31 are also value-identical inside the footprint.</p><p>With DTI = TP / (TP + 0.2 FP + 0.8 FN), discarding low-yield dots can reduce FP more than it reduces TP. This is consistent with the owner-supplied H33 claim <strong>0.2778</strong>. It does <em>not</em> identify hidden TP/FP uniquely or prove causation: visible-catalogue proximity may correlate with real unmapped faults, and no organizer submission receipt is present. GEMSDOE36 adds exactly 1,200 dots to H33, alongside the supplied decline to <strong>0.2750</strong>; those additions are not evidence of a better signal.</p><p>The newer historical GEMSDOE28 rung has 37,660 dots and is not the 40,199-dot r1 intermediate. Quoted scores are deliberately not fitted into a leaderboard predictor: nine heavily related files, unknown hidden truth and differing protocols cannot support an honest “beat the leader” forecast. The prompt’s 0.3195 / 0.4413 leader claims also conflict; neither is treated as freshly verified.</p><p><a href="docs/research/2026-10-26-gdx/fleet-audit.json">Reproducible nine-site raster/lineage audit</a> · <a href="docs/research/2026-10-25-lsm/why-h33-scored-0.2778.md">Earlier detailed H33 analysis (historical)</a></p></section>'''


def pages(ready):
    c, fleet = load("run-card.json"), load("fleet-audit.json")
    intro = '''<section class="intro"><div><p class="eyebrow">DOE GEMS / 26 October 2026 / evidence first</p><h1>No new submission.<br>A useful negative result.</h1><p class="lead">GDX-1 tested a genuinely different geothermal mechanism. The holdout did not support promotion. Download the single-band research GeoTIFF, keep the receipt, and protect the weekly slot.</p><div class="meta"><span>Format: passed</span><span>Science: negative</span><span>Global uniqueness: unknown</span><span>Organizer score: none</span></div></div></section>'''
    stats = '''<div class="evidence-strip"><article><span>GDX-1 HOLDOUT-DTI</span><strong>0.11965</strong><small>95% CI [0.10770, 0.13232]; 60,988 withheld positives</small></article><article><span>Same-protocol Core19</span><strong>0.13691</strong><small>Candidate delta −0.01725 [−0.03545, +0.00177]</small></article><article><span>New slot selected</span><strong>0</strong><small>3/3 experiment cap exhausted; no parameter rescue</small></article></div>'''
    home = frame("Current decision", intro + release(c) + stats + holdout(c) + '''<section class="section"><h2>Nine repositories. One evidence standard.</h2><p>Each priority site now has a read-only, pinned-snapshot executive review here: filenames, owner claims versus measurements, value aliases, and an explicit submission decision. Those separate repositories have not been edited.</p><div class="actions"><a class="button secondary" href="priority-executive-summary.html">Review GEMSDOE24 / 25 / 27 / 28 / 30 / 31 / 32 / 33 / 36</a><a class="text-link" href="geothermal-chemistry-review.html">Read the mechanism, novelty limits and stop →</a></div></section>''' + archive_note())
    guide_intro = '''<section class="intro"><div><p class="eyebrow">Download ≠ upload approval</p><h1>Keep the artifact.<br>Do not submit it.</h1><p class="lead">No visual inspection or manual quality flag is required. Automated evidence already gives the answer: GDX-1 is a negative experiment, not a competition recommendation.</p></div></section>'''
    fields = f'''<section class="section" id="identity"><h2>Exact research identity.</h2><p>This is the unique generated filename, not a claim of globally certified novelty. The note is {len(c['note'])}/140 characters. Copying either field does not authorize upload.</p><div class="identity"><label for="submission-name">Run / file stem</label><input id="submission-name" readonly value="{e(c['submission_name'], quote=True)}"><button class="copy-button" data-copy="submission-name">Copy name</button><label for="submission-note">Research note — keep the warning</label><textarea id="submission-note" rows="3" readonly>{e(c['note'])}</textarea><button class="copy-button" data-copy="submission-note">Copy note</button><p id="copy-status" role="status" aria-live="polite"></p></div></section>'''
    instructions = f'''<section class="section" id="instructions"><h2>What to do now.</h2><ol class="steps"><li><strong>Download the TIFF above for research only.</strong><p>The file is a single-band GeoTIFF on the exact template grid. Do not rename a historical raster and call it a new hypothesis.</p></li><li><strong>Let the verifier check it, not a human inspector.</strong><p><code>python scripts/verify_geothermal_chemistry_run.py</code> reopens bytes and catalogue masks, checks hashes / range / spacing, and recomputes the holdout CIs. It exits 0 for a valid negative finding; <code>--require-promote</code> correctly exits 2.</p></li><li><strong>Do not upload GDX-1 or spend a weekly slot.</strong><p>Both paired improvement gates failed. Global registry coverage, original-surface coverage, assignment, comparable-best reproduction, calibration / perturbation confirmation and current portal eligibility are unresolved. A format pass cannot override them.</p></li><li><strong>For a future eligible candidate only: use a separate slot-selection step.</strong><p>Require positive paired CIs versus the current comparable best, complete two-stage registry clearance and machine readiness first. Then verify current rules / weekly cap / deadline and use that candidate’s exact filename, name and ≤140-character note in the official portal. No competition upload has been made here. Do not assume the historical “5:00 p.m. ET” deadline or conflicting 0.4413 leader claim remains current.</p></li></ol><p class="fine">“Predicted values must be in range [0, 1]”: all in-footprint values are rechecked and finite; NaN outside follows the local published-template contract. The original rejected upload’s exact bytes and portal receipt are absent, so its root cause and acceptance of any replacement are not proven. No all-finite re-encoded fallback is offered as a new experiment.</p></section>'''
    guide = frame("Submission decision and exact download", guide_intro + release(c) + fields + instructions + holdout(c) + archive_note() + sources(), "Submission guide")
    rank = '''<section class="section" id="hypotheses"><h2>Four hypotheses, ranked before fitting.</h2><div class="table-wrap"><table><caption>Frozen in preregistration before the original started.json; no post-result tuning</caption><thead><tr><th>Rank</th><th>Mechanism / untried transform</th><th>Why it might work</th><th>Non-fault mimic / disposition</th></tr></thead><tbody><tr><th>1 · GDX-1</th><td>Co-measured quartz/cation/surface-temperature contrasts; site medians, own-observation normalization and effort control</td><td>Cooling / mixing above concealed upflow paths; not the earlier unsited max-temperature TAD threshold</td><td>Aquifer mixing, steam loss, uneven field sampling. Tested once; negative.</td></tr><tr><th>2</th><td>Well–spring thermal-population contrast with equal site weights</td><td>Different water residence / deep circulation without multiplying dense sample locations</td><td>Well depth, laboratory / use bias. Not run; no score.</td></tr><tr><th>3</th><td>Wavelet phase concordance of gravity and magnetic edges</td><td>Cross-scale persistence could separate shallow contact noise from deep structure</td><td>Non-fault lithologic contacts; related methods already exist. Not run; distinctness must be checked.</td></tr><tr><th>4</th><td>Signed scalar dilatation-conditioned permeability</td><td>Opening tendency may modulate conduit favorability without invented azimuth</td><td>Broad geodetic interpolation / hydrologic strain; no resolved stress direction. Not run.</td></tr></tbody></table></div><p class="fine">“Untried” means the exact transform was not found in indexed local lanes; fleet-wide novelty is not proven. Only rank 1 was implemented. The other ranks are next-session candidates, not permission to exceed the experiment cap.</p></section>'''
    mechanism = f'''<section class="section" id="mechanism"><h2>Physical interpretation, with the mimic beside it.</h2><p>{e(c['hypothesis'])} {e(c['mechanism'])} {e(c['non_fault_mimic'])} A geological story must beat a sampling-effort control; this one did not.</p><p>27,092 source records reduced to 2,398 unique observed grid sites. Co-measured quartz-cooling / cation-discordance / shared-excess marks have 539 / 551 / 526 contributing sites. Each mark is normalized by its own observed-site denominator; missing measurements are not zero evidence. No fluid label, fault distance, site ID, coordinates as predictors, or hidden-fault-derived field enters the feature transformer.</p><p>The candidate uses 12 channels; controls are the full 19 raw channels and six local-physics / effort channels. Train-only robust normalization and the same fixed HGB learner / seeds are used. Spatial support is bounded at 43 px; the 46 px guard includes the 3 px scoring halo. Feature support is separate from visible-fault exclusion. Whole fault components, not individual label pixels, are hidden.</p><p><a href="{BASE}preregistration.md">Frozen protocol</a> · <a href="{BASE}feature-receipt.json">Feature/provenance receipt</a> · <a href="{BASE}amendment-A1.md">A1 deviation and conservative cap accounting</a></p></section>'''
    next_session = '''<section class="section" id="next"><h2>Next session: repair evidence before adding complexity.</h2><ol class="spaced"><li>Resolve or formally classify the malformed GEMSDOE31 file; keep its SHA and invalid-cell count. Never silently drop it.</li><li>Obtain an actual lane assignment and all parallel saved surfaces / rasters, with frozen byte identities and receipts.</li><li>Restore the strongest comparable full-stack control and run it in the same support-safe folds before any slot proposal. Do not rank MSDB / FFL / TAD numbers from different protocols.</li><li>Only then preregister the well–spring contrast or a genuinely distinct, support-bounded hypothesis, with effort-only ablation, spatial CI, calibration and perturbation confirmation. No geometry jitter, seed search or residual “rescue” of this negative result.</li><li>Recheck official deadlines, eligibility and weekly slots independently of geological performance. Preserve the full owner prompt in README and reread it next session.</li></ol><p><a href="docs/research/2026-10-26-gdx/review.md">Full outcome, irregularities and reproduction</a></p></section>'''
    science = frame("GDX-1 negative research review", '''<section class="intro"><div><p class="eyebrow">Frozen test / conservative stop</p><h1>Geothermal chemistry.<br>A mechanism worth falsifying.</h1><p class="lead">The new signal did not outperform sampling effort or the same-protocol baseline. Own the negative result; do not promote an attractive geological narrative.</p></div></section>''' + release(c) + rank + mechanism + holdout(c) + novelty(c, ready) + next_session + sources(), "GDX-1 science")
    fleet_intro = '''<section class="intro"><div><p class="eyebrow">Read-only cross-repository audit</p><h1>Nine sites.<br>No verified winning file.</h1><p class="lead">A claimed leaderboard result is not a receipt. Each filename below is historical; none is recommended as a new submission. The newest GDX-1 research TIFF is available on the overview, but it also failed promotion.</p></div></section>'''
    fleet_page = frame("Nine-site executive summary", fleet_intro + priority_table(fleet) + lineage() + '''<section class="section"><h2>What was actually audited?</h2><p>The named historical leaders were restored by pinned SHA, reopened on the template grid, checked for value aliases and compared pairwise. Current public READMEs were separately retrieved at each frozen snapshot. Original surfaces and private / parallel rasters are not fully available. No defensible leaderboard estimate, organizer-confirmed score, or blanket “OK to submit” follows.</p><p>The four all-finite historical files from GEMSDOE30 / 32 / 33 / 36 fail only the shared local NaN-outside policy; values remain valid inside. This is not proof that a private portal would reject them and is not a diagnosis of the earlier range error.</p></section>''' + sources(), "Nine-site review")
    result = {"index.html": home, "executive-summary.html": guide,
              "geothermal-chemistry-review.html": science, "priority-executive-summary.html": fleet_page}
    notes = {
        "GEMSDOE24": "The 60,069-dot historical file is a reference, not a new candidate. Later README lanes must be judged on their own frozen evidence, not this supplied claim.",
        "GEMSDOE25": "The 44,090-dot d28 prediction values exactly match GEMSDOE30 inside the footprint. Their matching 0.2600 claims are not independent confirmations.",
        "GEMSDOE27": "The pinned public README calls a newer H31 DRCG file approved on a 27-reference audit and a roughly 0.235 projection. Neither is an organizer receipt or expanded-registry clearance; this review does not adopt that approval.",
        "GEMSDOE28": "The supplied best rung file contains 37,660 dots; do not confuse it with the 40,199-dot r1 intermediate in the verified H33 pruning lineage.",
        "GEMSDOE30": "Historical d28 is value-identical to GEMSDOE25. New GDX-1 is a different mechanism, but its paired improvement gate failed and global novelty remains unknown.",
        "GEMSDOE31": "The historical 40,199-dot file matches the earlier GEMSDOE28 r1 values. A different current CSDU reference has 2,610,312 non-finite in-footprint cells; it blocks GDX novelty clearance and is not repaired or ignored.",
        "GEMSDOE32": "H33-B2 contains 37,654 dots and exactly equals the earlier r1 subset more than 2 pixels from the catalogue. Its supplied 0.2778 is the highest of the nine historical claims, not a freshly verified organizer score.",
        "GEMSDOE33": "The historical H36 file contains 41,865 dots. Any newer claim in the pinned public repository must retain its protocol and uncertainty; the supplied 0.2632 alone does not forecast a new file.",
        "GEMSDOE36": "PINN-H42 contains H33 plus exactly 1,200 dots. The supplied claim falls from H33’s 0.2778 to 0.2750; this does not demonstrate successful physics-informed extrapolation.",
    }
    for r in fleet["rows"]:
        aliases = ", ".join(r["exact_value_alias_sites"]) or "No exact value alias among these nine historical leaders"
        format_text = "Passes the shared local published-format checks" if r["format_validation_passed"] else "Fails only local null-outside-template-footprint convention; inside-footprint values remain finite and valid. Not a portal-acceptance test"
        body = f'''<section class="intro"><div><p class="eyebrow">Pinned public snapshot / {e(r['public_snapshot_commit'][:12])}</p><h1>{r['site']}<br>Executive review.</h1><p class="lead">{e(notes[r['site']])}</p></div></section><section class="release"><div class="release-heading"><span class="pill failed">DO NOT RESUBMIT HISTORICAL BYTES</span><span class="pill unknown">Organizer score unverified</span></div><h2>One file identity. No fresh approval.</h2><p>Quoted historical owner claim: <strong>{r['quoted_owner_claim']}</strong>. This is not HOLDOUT-DTI, not ORGANIZER-CONFIRMED, and not a forecast. Leaderboard estimate for a new submission: <strong>not defensible</strong>. No new slot selected.</p><p class="filename">{e(r['historical_file'])}</p><dl><dt>Raster SHA-256</dt><dd><code>{r['raster_sha256']}</code></dd><dt>Dots</dt><dd>{r['dots']:,}</dd><dt>Value aliases</dt><dd>{e(aliases)}</dd><dt>Local format</dt><dd>{format_text}</dd><dt>Unique new submission?</dt><dd>No: these are already-published historical predictions. Byte differences / re-encoding do not create geological novelty. Global two-stage clearance is not claimed.</dd><dt>OK to submit?</dt><dd><strong>No recommendation / not approved here.</strong> Remote-site claims do not satisfy this repository’s expanded evidence gates.</dd></dl><div class="actions"><a class="button secondary" href="{e(r['source_url'])}?raw=true">Historical source TIFF — not a new candidate</a><a class="text-link" href="{r['site_url']}">Open original site ↗</a></div></section><section class="section"><h2>Review scope and evidence.</h2><p>The source raster and README were retrieved at pinned commits, not inferred from matching file names. This is a read-only executive review maintained in GEMSDOE30; the other site was not modified. Owner statements remain owner statements.</p><p><a href="{BASE}fleet-audit.json">Raster identities, pairwise checks and lineage</a> · <a href="{BASE}sources.json">Pinned README URLs and hashes</a> · <a href="priority-executive-summary.html#h33">Why H33-B2 improved in the supplied history</a></p><p>For a newly generated, format-validated research download with measured spatial evidence, see <a href="executive-summary.html">GDX-1</a> — explicitly negative, not an alternate submission recommendation.</p></section>'''
        result[f"priority-{r['site']}.html"] = frame(f"{r['site']} executive review", body, "Nine-site review")
    return result
